const activityById=Object.fromEntries(r.places.map(p=>[String(p.id),p.activity]));
const syncSchedule=schedule=>{for(const row of schedule||[]){if(Array.isArray(row)&&row[0]!=null&&activityById[String(row[0])])row[2]=activityById[String(row[0])]}}
for(const route of r.routes||[])for(const day of route.days||[])syncSchedule(day.schedule);
for(const plan of Object.values(r.routePlanning||{}))syncSchedule(plan.schedule);

